// The conflict encoding. One byte holds both which unique index an
// upsert names and what it does on collision, so the insert statement
// cache stays keyed by one mask and one byte:
//
//	0        no ON CONFLICT clause
//	1        ON CONFLICT DO NOTHING, on any unique index
//	2+2*i    target i, DO UPDATE
//	3+2*i    target i, DO NOTHING
const conflictAny = 1

// upsertTail builds the ON CONFLICT clause for one encoded conflict
// and one insert mask.
//
// The mask is what makes an upsert correct: it overwrites only the
// columns the caller ASSIGNED. Assigning every column would revert
// each one the caller left out to its default, on the row that
// already exists — a silent data loss that reads as an upsert working.
func upsertTail(conflict uint8, mask uint64) string {
	if conflict == conflictAny {
		return " ON CONFLICT DO NOTHING"
	}
	spec, i := conflictSpecs[(conflict-2)/2], (conflict-2)/2
	if conflict%2 == 1 {
		return spec + " DO NOTHING"
	}
	set := assignable(i, mask)
	if len(set) == 0 {
		// Nothing to overwrite. DO UPDATE SET with an empty list is not
		// SQL, and leaving the row alone is what the caller asked for.
		return spec + " DO NOTHING"
	}
	return spec + " DO UPDATE SET " + joinAssign(set)
}

// conflictSpecs is one inference specification per target, in
// declaration order. A PARTIAL unique index carries its predicate:
// PostgreSQL infers the index from the keys and the predicate
// together, and without it the insert fails at run time — on the first
// row that collides, which a test inserting distinct rows never sees.
var conflictSpecs = []string{
	" ON CONFLICT (\"id\")",
}

// assignable is the columns target i may overwrite, given the mask.
func assignable(i uint8, mask uint64) []string {
	set := make([]string, 0, 16)
	switch i {
	case 0:
		if mask&(1<<2) != 0 {
			set = append(set, "updated_at")
		}
		if mask&(1<<3) != 0 {
			set = append(set, "instance_id")
		}
		if mask&(1<<4) != 0 {
			set = append(set, "definition_id")
		}
		if mask&(1<<5) != 0 {
			set = append(set, "node_id")
		}
		if mask&(1<<6) != 0 {
			set = append(set, "iteration_id")
		}
		if mask&(1<<7) != 0 {
			set = append(set, "type")
		}
		if mask&(1<<8) != 0 {
			set = append(set, "status")
		}
		if mask&(1<<9) != 0 {
			set = append(set, "locked_by")
		}
		if mask&(1<<10) != 0 {
			set = append(set, "lock_expires")
		}
		if mask&(1<<11) != 0 {
			set = append(set, "payload")
		}
		if mask&(1<<12) != 0 {
			set = append(set, "retries")
		}
		if mask&(1<<13) != 0 {
			set = append(set, "max_retries")
		}
		if mask&(1<<14) != 0 {
			set = append(set, "repeats_remaining")
		}
		if mask&(1<<15) != 0 {
			set = append(set, "next_run_at")
		}
		if mask&(1<<16) != 0 {
			set = append(set, "last_error")
		}
		if mask&(1<<17) != 0 {
			set = append(set, "deleted_at")
		}
	}
	return set
}

// OnConflictID upserts on the unique index over (id).
//
// The row that already exists keeps every column this insert did
// not assign. Follow with DoNothing() to leave it untouched
// entirely.
func (n *Ins) OnConflictID() *Ins {
	n.conflict = 2
	return n
}

// DoNothing makes the insert a no-op when the row is already there —
// the idempotent insert, and the commonest upsert there is.
//
// On its own it names no index, so ANY unique violation is the no-op:
//
//	n.DoNothing()                  // ON CONFLICT DO NOTHING
//	n.OnConflictID().DoNothing()  // only on that one index
//
// Insert then returns runtime.ErrNoRows when nothing was written,
// because DO NOTHING suppresses the RETURNING row: there is no row to
// return, and reporting a zero-valued one as inserted would be a lie.
func (n *Ins) DoNothing() *Ins {
	if n.conflict < 2 {
		n.conflict = conflictAny
		return n
	}
	n.conflict |= 1
	return n
}

// joinAssign renders the DO UPDATE SET list for the columns the caller
// assigned. The punctuation comes from the back end, never from here.
func joinAssign(set []string) string {
	out := ""
	for i, c := range set {
		if i > 0 {
			out += ", "
		}
		out += assignExcluded(c)
	}
	return out
}

var assignFor = map[string]string{
	"updated_at":        "\"updated_at\" = EXCLUDED.\"updated_at\"",
	"instance_id":       "\"instance_id\" = EXCLUDED.\"instance_id\"",
	"definition_id":     "\"definition_id\" = EXCLUDED.\"definition_id\"",
	"node_id":           "\"node_id\" = EXCLUDED.\"node_id\"",
	"iteration_id":      "\"iteration_id\" = EXCLUDED.\"iteration_id\"",
	"type":              "\"type\" = EXCLUDED.\"type\"",
	"status":            "\"status\" = EXCLUDED.\"status\"",
	"locked_by":         "\"locked_by\" = EXCLUDED.\"locked_by\"",
	"lock_expires":      "\"lock_expires\" = EXCLUDED.\"lock_expires\"",
	"payload":           "\"payload\" = EXCLUDED.\"payload\"",
	"retries":           "\"retries\" = EXCLUDED.\"retries\"",
	"max_retries":       "\"max_retries\" = EXCLUDED.\"max_retries\"",
	"repeats_remaining": "\"repeats_remaining\" = EXCLUDED.\"repeats_remaining\"",
	"next_run_at":       "\"next_run_at\" = EXCLUDED.\"next_run_at\"",
	"last_error":        "\"last_error\" = EXCLUDED.\"last_error\"",
	"deleted_at":        "\"deleted_at\" = EXCLUDED.\"deleted_at\"",
}

func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	if st := insCache.Get(key); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTail(conflict, mask) + insReturning
	}
	return insCache.Put(key, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.InstanceID)
		case 4:
			args = append(args, n.row.DefinitionID)
		case 5:
			args = append(args, n.row.NodeID)
		case 6:
			args = append(args, n.row.IterationID.Arg())
		case 7:
			args = append(args, n.row.Type)
		case 8:
			args = append(args, n.row.Status)
		case 9:
			args = append(args, n.row.LockedBy.Arg())
		case 10:
			args = append(args, n.row.LockExpires.Arg())
		case 11:
			args = append(args, n.row.Payload)
		case 12:
			args = append(args, n.row.Retries)
		case 13:
			args = append(args, n.row.MaxRetries)
		case 14:
			args = append(args, n.row.RepeatsRemaining)
		case 15:
			args = append(args, n.row.NextRunAt)
		case 16:
			args = append(args, n.row.LastError.Arg())
		case 17:
			args = append(args, n.row.DeletedAt.Arg())
		}
	}
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		if n.conflict != 0 && n.conflict%2 == 1 {
			// DO NOTHING suppresses RETURNING, so no row means the row was
			// already there — the success case of an idempotent insert.
			return out, runtime.ErrConflict
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes one row and reads back every column, so database-computed
// defaults — a generated id, a now() timestamp — land in r rather than
// needing a second SELECT that would race every other writer.
//
// Every insertable column is written, including zero values. storm does
// not treat a zero as 'unset': that guess is why other ORMs cannot insert
// a false, a 0 or an empty string into a column with a default.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 18)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.InstanceID)
	args = append(args, r.DefinitionID)
	args = append(args, r.NodeID)
	args = append(args, r.IterationID.Arg())
	args = append(args, r.Type)
	args = append(args, r.Status)
	args = append(args, r.LockedBy.Arg())
	args = append(args, r.LockExpires.Arg())
	args = append(args, r.Payload)
	args = append(args, r.Retries)
	args = append(args, r.MaxRetries)
	args = append(args, r.RepeatsRemaining)
	args = append(args, r.NextRunAt)
	args = append(args, r.LastError.Arg())
	args = append(args, r.DeletedAt.Arg())
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"id",
	"created_at",
	"updated_at",
	"instance_id",
	"definition_id",
	"node_id",
	"iteration_id",
	"type",
	"status",
	"locked_by",
	"lock_expires",
	"payload",
	"retries",
	"max_retries",
	"repeats_remaining",
	"next_run_at",
	"last_error",
	"deleted_at",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [18]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer across every row, and fills it with POINTERS
// into the caller's slice rather than copies.
//
// Both halves matter. The driver consumes each slice before asking for
// the next, so one buffer is safe. And boxing a pointer into an `any`
// does not allocate while boxing a value does — at a thousand rows that
// is one allocation per column per row, or none. Measured: the first cut
// boxed values and cost 7 allocations per row.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.ID
	s.buf[1] = &r.CreatedAt
	s.buf[2] = &r.UpdatedAt
	s.buf[3] = &r.InstanceID
	s.buf[4] = &r.DefinitionID
	s.buf[5] = &r.NodeID
	s.buf[6] = r.IterationID.Ptr()
	s.buf[7] = &r.Type
	s.buf[8] = &r.Status
	s.buf[9] = r.LockedBy.Ptr()
	s.buf[10] = r.LockExpires.Ptr()
	s.buf[11] = &r.Payload
	s.buf[12] = &r.Retries
	s.buf[13] = &r.MaxRetries
	s.buf[14] = &r.RepeatsRemaining
	s.buf[15] = &r.NextRunAt
	s.buf[16] = r.LastError.Ptr()
	s.buf[17] = r.DeletedAt.Ptr()
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through the driver's COPY protocol: ONE round
// trip regardless of row count, because COPY is a different wire path and
// not a faster loop over INSERT.
//
// It returns no rows. COPY has no RETURNING, so a caller who needs
// database-generated ids must supply them — which is why the primary key
// is in copyCols and must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "jobs", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every
// insertable column, because a batch of a thousand rows that each chose
// a different column set would compile a thousand statements and defeat
// the point of batching them.
//
// WantRows is false: a batched insert reports a count. Asking for
// RETURNING here would mean scanning a result per statement, which is
// exactly the per-row work a batch exists to avoid.
func InsertOp(r Row) runtime.BatchOp {
	var mask uint64
	mask |= 1 << 0
	mask |= 1 << 1
	mask |= 1 << 2
	mask |= 1 << 3
	mask |= 1 << 4
	mask |= 1 << 5
	mask |= 1 << 6
	mask |= 1 << 7
	mask |= 1 << 8
	mask |= 1 << 9
	mask |= 1 << 10
	mask |= 1 << 11
	mask |= 1 << 12
	mask |= 1 << 13
	mask |= 1 << 14
	mask |= 1 << 15
	mask |= 1 << 16
	mask |= 1 << 17
	st := stmtForInsertNoReturn(mask, 0)
	args := make([]any, 0, 18)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.InstanceID)
	args = append(args, r.DefinitionID)
	args = append(args, r.NodeID)
	args = append(args, r.IterationID.Arg())
	args = append(args, r.Type)
	args = append(args, r.Status)
	args = append(args, r.LockedBy.Arg())
	args = append(args, r.LockExpires.Arg())
	args = append(args, r.Payload)
	args = append(args, r.Retries)
	args = append(args, r.MaxRetries)
	args = append(args, r.RepeatsRemaining)
	args = append(args, r.NextRunAt)
	args = append(args, r.LastError.Arg())
	args = append(args, r.DeletedAt.Arg())
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// Op is this Ins as a queueable statement, conflict clause and all —
// the bulk upsert.
//
// InsertOp above takes a Row and writes every column, so a thousand of
// them share one statement. This takes the BUILDER, so it carries the
// mask and the ON CONFLICT the caller chose: ingesting a batch that
// should overwrite what is already there, or skip it, needs both and
// could otherwise only be done one round trip at a time.
//
// One statement per distinct (mask, conflict) pair, cached like every
// other. Assign the same columns on every row of a batch and it stays
// one; vary them and it is one per shape, which is the cost of asking.
//
// WantRows is false, as for InsertOp: a batch reports counts. A DO
// NOTHING that skipped a row is a zero in that count — the batch
// cannot say which rows were skipped, only how many.
func (n *Ins) Op() (runtime.BatchOp, error) {
	if n.set == 0 {
		return runtime.BatchOp{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsertNoReturn(n.set, n.conflict)
	if st.Err != nil {
		return runtime.BatchOp{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.InstanceID)
		case 4:
			args = append(args, n.row.DefinitionID)
		case 5:
			args = append(args, n.row.NodeID)
		case 6:
			args = append(args, n.row.IterationID.Arg())
		case 7:
			args = append(args, n.row.Type)
		case 8:
			args = append(args, n.row.Status)
		case 9:
			args = append(args, n.row.LockedBy.Arg())
		case 10:
			args = append(args, n.row.LockExpires.Arg())
		case 11:
			args = append(args, n.row.Payload)
		case 12:
			args = append(args, n.row.Retries)
		case 13:
			args = append(args, n.row.MaxRetries)
		case 14:
			args = append(args, n.row.RepeatsRemaining)
		case 15:
			args = append(args, n.row.NextRunAt)
		case 16:
			args = append(args, n.row.LastError.Arg())
		case 17:
			args = append(args, n.row.DeletedAt.Arg())
		}
	}
	return runtime.BatchOp{SQL: st.SQL, Args: args}, nil
}

// stmtForInsertNoReturn is stmtForInsert without RETURNING, for the
// batch path. Its own cache: the two differ by a suffix, and sharing
// one would hand a batch the statement that asks for rows back.
func stmtForInsertNoReturn(mask uint64, conflict uint8) *runtime.Stmt {
	key := mask | uint64(conflict)<<nInsertable
	if st := insOpCache.Get(key); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := ""
	if conflict > 0 {
		suffix = upsertTail(conflict, mask)
	}
	return insOpCache.Put(key, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// UpdateOp is this Mut's update as a queueable statement.
//
// The optimistic lock still applies, but the caller must check the
// affected count the batch reports: a stale write inside a batch is not
// an error the driver raises, it is a zero the caller has to notice.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForMask(m.dirty)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.InstanceID)
		case 2:
			args = append(args, m.row.DefinitionID)
		case 3:
			args = append(args, m.row.NodeID)
		case 4:
			args = append(args, m.row.IterationID.Arg())
		case 5:
			args = append(args, m.row.Type)
		case 6:
			args = append(args, m.row.Status)
		case 7:
			args = append(args, m.row.LockedBy.Arg())
		case 8:
			args = append(args, m.row.LockExpires.Arg())
		case 9:
			args = append(args, m.row.Payload)
		case 10:
			args = append(args, m.row.Retries)
		case 11:
			args = append(args, m.row.MaxRetries)
		case 12:
			args = append(args, m.row.RepeatsRemaining)
		case 13:
			args = append(args, m.row.NextRunAt)
		case 14:
			args = append(args, m.row.LastError.Arg())
		case 15:
			args = append(args, m.row.DeletedAt.Arg())
		}
	}
	args = append(args, m.row.ID)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp marks the row deleted, exactly as Delete does: a queued
// delete and a direct one must not differ in whether the row survives.
// HardDeleteOp is the queueable form of HardDelete.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: softDeleteSQL, Args: []any{iD}}
}

// HardDeleteOp removes the row for real, as a queueable statement.
func HardDeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: hardDeleteSQL, Args: []any{iD}}
}

// RestoreOp clears the mark, as a queueable statement.
func RestoreOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: restoreSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "jobs"

// stmtForMask compiles the UPDATE for one dirty mask, once.
func stmtForMask(mask uint64) *runtime.Stmt {
	if st := updCache.Get(mask); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		if mask&(1<<uint(i)) != 0 {
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 3)
	where = append(where, pkFrags[:]...)
	// A deleted row is not updatable: every read here says it is gone.
	where = append(where, runtime.Frag{A: `"deleted_at" IS NULL`})
	return updCache.Put(mask, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, ""))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 {
		return nil
	}
	st := stmtForMask(m.dirty)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.InstanceID)
		case 2:
			args = append(args, m.row.DefinitionID)
		case 3:
			args = append(args, m.row.NodeID)
		case 4:
			args = append(args, m.row.IterationID.Arg())
		case 5:
			args = append(args, m.row.Type)
		case 6:
			args = append(args, m.row.Status)
		case 7:
			args = append(args, m.row.LockedBy.Arg())
		case 8:
			args = append(args, m.row.LockExpires.Arg())
		case 9:
			args = append(args, m.row.Payload)
		case 10:
			args = append(args, m.row.Retries)
		case 11:
			args = append(args, m.row.MaxRetries)
		case 12:
			args = append(args, m.row.RepeatsRemaining)
		case 13:
			args = append(args, m.row.NextRunAt)
		case 14:
			args = append(args, m.row.LastError.Arg())
		case 15:
			args = append(args, m.row.DeletedAt.Arg())
		}
	}
	args = append(args, m.row.ID)
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	return nil
}

// softDeleteSQL marks one live row. It matches on `"deleted_at" IS NULL`, so
// deleting an already-deleted row reports runtime.ErrNoRow rather than
// silently re-stamping it with a later time.
var softDeleteSQL = runtime.SpliceSections(`UPDATE "jobs" SET "deleted_at" = now()`, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: append(pkFrags[:], runtime.Frag{A: `"deleted_at" IS NULL`})},
}, "").SQL

// Delete marks one row deleted. The row stays in the table and keeps its
// keys; every read generated in this package stops returning it.
//
// A row that was already deleted is runtime.ErrNoRow, not success — the
// same answer a hard delete gives for a row that is not there.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, softDeleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

var hardDeleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// HardDelete removes the row for real, deleted or not. It is the only
// function in this package that destroys data, which is why it is not
// spelled Delete.
func HardDelete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, hardDeleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

var restoreSQL = runtime.SpliceSections(`UPDATE "jobs" SET "deleted_at" = NULL`, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: append(pkFrags[:], runtime.Frag{A: `"deleted_at" IS NOT NULL`})},
}, "").SQL

// Restore clears the mark. A row that was not deleted is runtime.ErrNoRow:
// restoring something that was never gone is a caller believing something
// untrue about the row, and reporting success would leave them believing it.
func Restore(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, restoreSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}
